204	    void concurrentTermUpdates() throws Exception {
205	        long docId = createDocument(newRequestId(), "[\"en\"]", "[]");
206	        int threads = 4;
207	        ExecutorService pool = Executors.newFixedThreadPool(threads);
208	        CountDownLatch gate = new CountDownLatch(1);
209	        List<Future<ApiResult>> futures = new ArrayList<>();
210	        for (int i = 0; i < threads; i++) {
211	            final int n = i;
212	            futures.add(pool.submit(() -> {
213	                gate.await();
214	                return updateTerms(docId, 0,
215	                        "[{\"sourceTerm\":\"术语" + n + "\",\"language\":\"en\","
216	                                + "\"requiredTranslation\":\"term" + n + "\"}]", newRequestId());
217	            }));
218	        }
219	        gate.countDown();
220	        int success = 0;
221	        int conflict = 0;
222	        for (Future<ApiResult> future : futures) {
223	            int status = future.get(30, TimeUnit.SECONDS).status();
224	            if (status == 201) {
225	                success++;
226	            } else if (status == 409) {
227	                conflict++;
228	            }
229	        }
230	        pool.shutdown();
231	
232	        assertThat(success).isEqualTo(1);
233	        assertThat(conflict).isEqualTo(threads - 1);
234	        assertThat(jdbc.queryForObject(
235	                "SELECT COUNT(*) FROM term_version WHERE document_id = ?", Integer.class, docId))
236	                .isEqualTo(1);
237	        Integer termVersion = jdbc.queryForObject(
238	                "SELECT term_version FROM document WHERE document_id = ?", Integer.class, docId);
239	        assertThat(termVersion).isEqualTo(1);
240	    }
241	}
