@Transactional
public TrainResponse activate(documentId, trainKey) {
    DocumentRow document = lockDocument(documentId);
    ReleaseTrainRow train = findTrainOrThrow(documentId, trainKey);
    if (train.status() == DRAFT) throw conflict("列车尚未 READY");
    if (train.status() == CANCELLED) throw conflict("列车已取消");
    if (train.status() == ACTIVATED) throw conflict("列车已激活");  // idempotent replay handled by requestId
    if (Instant.now().isBefore(train.plannedAt())) throw conflict("未到计划发布时间");
    List<TrainLocaleRow> locales = listTrainLocales;
