                .isEqualTo(201);
        readyTrain(docId, "train-approve");

        // 模拟审核人撤回批准（删除批准记录）
        jdbc.update("DELETE FROM approval WHERE document_id = ? AND segment_id = 's1' AND language = 'fr'",
