        for (var pointer : pointers.body().get("pointers")) {
            assertThat(pointer.get("releasedVersion").asInt()).isEqualTo(1);
        }
        assertThat(jdbc.queryForObject(
                "SELECT COUNT(*) FROM train_snapshot WHERE document_id = ?", Integer.class, docId))
